        Scanner sc = new Scanner(System.in);
        String input = sc.next();
        long n = Long.parseLong(input.substring(0, input.length() - 1));
        char s = input.charAt(input.length() - 1);

        long total = 0;

        // Determine the position of the seat in the serving order
        long pos;
        if (s == 'f') pos = 1;
        else if (s == 'e') pos = 2;
        else if (s == 'd') pos = 3;
        else if (s == 'a') pos = 4;
        else if (s == 'b') pos = 5;
        else pos = 6; // 'c'

        // Determine which attendant serves the row and the group
        long group;
        long offset;
        if (n % 2 == 1) {
            // Attendant 1 serves odd rows
            group = (n - 1) / 4;
            offset = group * 2 + 1;
        } else {
            // Attendant 2 serves even rows
            group = (n - 2) / 4;
            offset = group * 2 + 2;
        }

        // Calculate the time taken to serve all rows before the current group
        // Each group takes 6 seconds for serving (3 rows * 2 attendants * 1 sec each passenger? No, each row has 6 seats)
        // Wait, each group consists of two rows (att1 and att2), each row takes 6 seconds (6 seats)
        // So per group: 6 + 6 = 12 seconds for serving, plus movement time
        // Movement time between groups: first group starts at rows 1 and 3. Next group moves 1 row forward (rows 2 and 4), then next moves 3 rows forward (rows 5 and 7), etc.
        // The movement pattern is: after serving a group, move 1 row, then 3 rows, alternating.
        // But the total movement time for all previous groups needs to be calculated.

        // Total time = serving time of all previous groups + movement time of all previous groups + serving time in current group up to the row + serving time in the row up to the seat

        // Serving time per group: 6 (row1) + 6 (row2) = 12 seconds
        // Movement time: first group (rows 1,3) -> next group (rows 2,4): move 1 row (1 sec)
        // Then next group (rows 5,7): move 3 rows (3 sec)
        // Then next group (rows 6,8): move 1 row (1 sec)
        // Pattern: 1, 3, 1, 3, ...

        // Number of previous groups: group
        // Movement time for previous groups:
        // If group is 0, no movement
        // For group > 0:
        // The movement times alternate between 1 and 3, starting with 1 for the first movement
        // Total movement time = sum of first 'group' movements
        // The sequence is 1, 3, 1, 3, ...
        // For 'group' movements:
        // If group is even: (group/2) * (1+3) = group/2 * 4
        // If group is odd: (group/2) * 4 + 1

        long movementTime = 0;
        if (group > 0) {
            long pairs = group / 2;
            movementTime = pairs * 4;
            if (group % 2 == 1) {
                movementTime += 1;
            }
        }

        // Serving time for all previous groups: group * 12
        long servingTime = group * 12;

        // Time to serve up to the current row in the current group
        // The current group serves rows offset and offset+2
        // If the row is the first in the group (offset), time is 0
        // If the row is the second in the group (offset+2), time is 6
        long rowInGroupTime = 0;
        if (n != offset) {
            rowInGroupTime = 6;
        }

        // Time to serve up to the seat in the row
        long seatTime = pos;

        total = movementTime + servingTime + rowInGroupTime + seatTime;

        System.out.println(total);
    }
